function furniture(x, y, l, w, r) {
	push()
	//shorting dimensions if they would cause 'overhang'
	wPct= w/r
	let _wG_1 = 0; while ((x+wPct>0.9) && ++_wG_1 < 20000){
		w= w-0.5
		wPct= w/r	
	}

	lPct= l/r

	let _wG_2 = 0; while ((y+lPct>0.9) && ++_wG_2 < 20000){
		l= l-0.5
		lPct= l/r	
	}

	let placement=isoFloor(x, y)
	translate(placement.x, placement.y)
	//x, y marks upper left
	//currently: random(-r / 2, r / 2), random(r/10, r / 3), random(r / 8, r / 2), random(r / 8, r / 2))

	pt1 = createVector(0, 0)
	pt2 = createVector(w * sin(1.047) / sin(PI / 2), w * sin(PI / 6) / sin(PI / 2))
	pt3 = createVector(pt2.x - l * sin(1.047) / sin(PI / 2), pt2.y + l * sin(0.524) / sin(PI / 2))
	pt4 = createVector(-l * sin(1.047) / sin(PI / 2), l / 2)
	fill(0)

	//defining different furniture

	fStyle='nothing'

	if(x<0.2 && w>r/3){
		//is bed
		fStyle='bed'
		line(pt1.x, pt1.y, pt1.x, pt1.y-roomSize/10)
		line(pt4.x, pt4.y, pt4.x, pt4.y-roomSize/10)
		line(pt1.x, pt1.y-roomSize/20, pt4.x, pt4.y-roomSize/20)
	}
	if(x<0.2 && l>r/3 && w<r/3){
		//is couch
		fStyle='couch'
		w= r/8
	pt1 = createVector(0, 0)
	pt2 = createVector(w * sin(1.047) / sin(PI / 2), w * sin(PI / 6) / sin(PI / 2))
	pt3 = createVector(pt2.x - l * sin(1.047) / sin(PI / 2), pt2.y + l * sin(0.524) / sin(PI / 2))
	pt4 = createVector(-l * sin(1.047) / sin(PI / 2), l / 2)
		push()
		fill(0)
		quad(pt1.x, pt1.y, pt1.x,pt1.y-roomSize/10, pt4.x, pt4.y-roomSize/10, pt4.x, pt4.y)
		pop()
	}

	if(l<r/5 && w<r/5){
		//is pedestal
fStyle='pedestal'
	let center= p5.Vector.lerp(pt1, pt3, 0.5)
	//let xCenter= p5.Vector.lerp(pt2, pt4, 0.5)
	arc(center.x, center.y-r/20,r/10, r/8, -PI/4, PI+PI/4, CHORD)
		for(let i=0; i<8; i++){
			endMover=random(-r/7, r/7)
			curve(center.x, center.y, center.x, center.y-r/12, center.x+endMover, center.y-r/6, center.x+(endMover*2), center.y-r/8)
		}
	}

	if(x>0.2 && l>r/3 && w<r/3){
		//is desk, 
		fStyle='desk'
			chair(-0.1, 0.2, r, 1)
	}

	//next up 'table' as in dinner table, if both l & w are largish- put chairs on left and back

	if(l>r/3 && w>r/3 && x>0.2){
		//is table
		fStyle='table'
		chair(-0.1, 0.2, r, 1)
		chair(0.2, -0.1, r, 2)
	}



	//draws quad and 'legs'
	quad(pt1.x, pt1.y, pt2.x, pt2.y, pt3.x, pt3.y, pt4.x, pt4.y)

	line(pt2.x, pt2.y, pt2.x, pt2.y + roomSize / 12)
line(pt3.x, pt3.y, pt3.x, pt3.y+roomSize/12)
	line(pt4.x, pt4.y, pt4.x, pt4.y+roomSize/12)


	pop()
}

